export const listTeamUsersQueryOffsetMin = 0;



export const ListTeamUsersQueryParams = zod.object({
  "role": zod.enum(['admin', 'volunteer']),
  "q": zod.coerce.string().max(listTeamUsersQueryQMax).optional(),
  "limit": zod.coerce.number().int().min(1).max(listTeamUsersQueryLimitMax).default(listTeamUsersQueryLimitDefault),
  "offset": zod.coerce.number().int().min(listTeamUsersQueryOffsetMin).default(listTeamUsersQueryOffsetDefault)
})

export const ListTeamUsersResponse = zod.object({
  "users": zod.array(zod.object({
  "id": zod.string().uuid(),
  "email": zod.string().email(),
  "firstName": zod.string(),
  "lastName": zod.string(),
  "phone": zod.string().nullable(),
  "role": zod.enum(['admin', 'volunteer']),
  "emailVerifiedAt": zod.coerce.date().nullable(),
  "isActive": zod.boolean(),
  "isTestAccount": zod.boolean().optional(),
  "lastLoginAt": zod.coerce.date().nullable(),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})),
  "total": zod.number().int(),
  "limit": zod.number().int(),
  "offset": zod.number().int()
})


export const inviteAdminBodyFirstNameMax = 100;

export const inviteAdminBodyLastNameMax = 100;

export const inviteAdminBodyEmailMax = 254;



export const InviteAdminBody = zod.object({
  "firstName": zod.string().min(1).max(inviteAdminBodyFirstNameMax),
  "lastName": zod.string().min(1).max(inviteAdminBodyLastNameMax),
  "email": zod.string().email().max(inviteAdminBodyEmailMax)
})

export const InviteAdminResponse = zod.object({
  "ok": zod.boolean(),
  "email": zod.string(),
  "delivery": zod.enum(['sent', 'logged', 'failed', 'suppressed']),
  "message": zod.string()
})


export const SetUserActiveStatusParams = zod.object({
  "userId": zod.coerce.string().uuid()
})

export const SetUserActiveStatusBody = zod.object({
  "isActive": zod.boolean()
})

export const SetUserActiveStatusResponse = zod.object({
  "id": zod.string().uuid(),
  "email": zod.string().email(),
  "firstName": zod.string(),
  "lastName": zod.string(),
  "phone": zod.string().nullable(),
  "role": zod.enum(['admin', 'volunteer']),
  "emailVerifiedAt": zod.coerce.date().nullable(),
  "isActive": zod.boolean(),
  "isTestAccount": zod.boolean().optional(),
  "lastLoginAt": zod.coerce.date().nullable(),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})


/**
 * Requires an active, verified session. Returns no password, Google subject, session version, or admin notes. Authentication failures are JSON with error and code.
 */
export const GetMeResponse = zod.object({
  "user": zod.object({
  "id": zod.string().uuid(),
  "email": zod.string().email(),
  "firstName": zod.string(),
  "lastName": zod.string(),
  "phone": zod.string().nullable(),
  "role": zod.enum(['admin', 'volunteer']),
  "emailVerifiedAt": zod.coerce.date().nullable(),
  "isActive": zod.boolean(),
  "isTestAccount": zod.boolean().optional(),
  "lastLoginAt": zod.coerce.date().nullable(),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
}),
  "role": zod.enum(['admin', 'volunteer']),
  "verified": zod.boolean(),
  "agreementRequired": zod.boolean().optional(),
  "currentAgreementVersion": zod.string().optional(),
  "testPersona": zod.string().optional().describe('Built-in QA persona key for the current test account only'),
  "profile": zod.union([zod.object({
  "id": zod.string().uuid(),
  "userId": zod.string().uuid(),
  "county": zod.string(),
  "dateOfBirth": zod.string().nullable(),
  "addressLine1": zod.string().nullable(),
  "city": zod.string().nullable(),
  "state": zod.string().nullable(),
  "zip": zod.string().nullable(),
  "emergencyContactName": zod.string().nullable(),
  "emergencyContactRelationship": zod.string().nullable(),
  "emergencyContactPhone": zod.string().nullable(),
  "startDate": zod.string().nullable(),
  "status": zod.enum(['onboarding', 'active', 'inactive']),
  "onboardingAnswers": zod.record(zod.string(), zod.unknown()),
  "onboardingCompletedAt": zod.coerce.date().nullable(),
  "availabilityNotes": zod.string().nullable(),
  "certificationStatus": zod.enum(['not_started', 'in_progress', 'complete']),
  "certificationCompletedAt": zod.string().nullable(),
  "certificationExpiresAt": zod.string().nullable(),
  "backgroundCheckStatus": zod.enum(['not_started', 'pending', 'cleared', 'not_cleared']),
  "backgroundCheckSubmittedAt": zod.string().nullable(),
  "backgroundCheckClearedAt": zod.string().nullable(),
  "agreementAcknowledgedAt": zod.coerce.date().nullable(),
  "agreementVersion": zod.string().nullable(),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
}),zod.null()])
})


